// ===== HTTP helpers =====
fn http_date(ts: std::time::SystemTime) -> String {
    // Format as "Fri, 04 Sep 2026 03:07:02 GMT"
    // Use chrono? No chrono available? We have time? No. Implement manually via libc? Simpler: use std + manual conversion via `time`? We don't have time crate. Use system time to seconds since epoch, then convert to date via algorithm.
    // We'll implement conversion from unix timestamp to RFC1123.
    let dur = ts.duration_since(std::time::UNIX_EPOCH).unwrap_or_default();
    let secs = dur.as_secs() as i64;
    // Days since epoch, etc.
    // Use algorithm for civil date
    let days = secs.div_euclid(86400);
    let secs_of_day = secs.rem_euclid(86400);
    let h = secs_of_day / 3600;
    let m = (secs_of_day % 3600) / 60;
    let s = secs_of_day % 60;
    // Convert days to date (1970-01-01 is Thursday)
    // Use Howard Hinnant's algorithm
    let z = days + 719468;
    let era = if z >= 0 { z } else { z - 146096 };
    let doe = (era - era.div_euclid(146097) * 146097) as u64; // [0, 146096]
    let yoe = (doe - doe/36524 + doe/146096) / 365; // [0, 399]
    let mut y = (yoe as i64) + era.div_euclid(146097) * 400;
    let doy = doe - (365*yoe + yoe/4 - yoe/100); // [0, 365]
    let mp = (5*doy + 2)/153; // [0, 11]
    let d = (doy - (153*mp+2)/5 + 1) as u64; // [1, 31]
    let mth = if mp < 10 { mp+3 } else { mp-9 }; // [1, 12]
    y += if mth <= 2 { 1 } else { 0 };
    // Weekday: 1970-01-01 Thursday (4), so (days+4)%7 where 0=Sunday? Let's compute: days=0 -> Thursday. Thursday is 4 if Sunday=0. So w = (days+4)%7
    let w = ((days + 4).rem_euclid(7)) as usize;
    let weekdays = ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];
    let months = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
    format!("{}, {:02} {} {} {:02}:{:02}:{:02} GMT", weekdays[w], d, months[(mth-1) as usize], y, h, m, s)
}

fn parse_http_date(s: &str) -> Option<std::time::SystemTime> {
    // Parse "Fri, 04 Sep 2026 03:07:02 GMT" to SystemTime
    // Format: "%a, %d %b %Y %H:%M:%S GMT"
    let parts: Vec<&str> = s.split_whitespace().collect();
    if parts.len() != 6 { return None; }
    // parts[0]="Fri,", parts[1]="04", parts[2]="Sep", parts[3]="2026", parts[4]="03:07:02", parts[5]="GMT"
    if parts[5] != "GMT" { return None; }
    let day: u64 = parts[1].parse().ok()?;
    let mon = match parts[2] {
        "Jan"=>1,"Feb"=>2,"Mar"=>3,"Apr"=>4,"May"=>5,"Jun"=>6,"Jul"=>7,"Aug"=>8,"Sep"=>9,"Oct"=>10,"Nov"=>11,"Dec"=>12,
        _=>return None,
    };
    let year: i64 = parts[3].parse().ok()?;
    let tparts: Vec<&str> = parts[4].split(':').collect();
    if tparts.len()!=3 {return None;}
    let h: u64 = tparts[0].parse().ok()?;
    let m: u64 = tparts[1].parse().ok()?;
    let sec: u64 = tparts[2].parse().ok()?;
    // Convert to days since epoch via algorithm reverse
    // Use days_from_civil
    let y = if mon <= 2 { year-1 } else { year };
    let era = if y >= 0 { y } else { y-399 } .div_euclid(400);
    let yoe = (y - era*400) as u64; // [0,399]
    let doy = (153*((if mon>2 {mon-3} else {mon+9}) as u64)+2)/5 + (day-1);
    let doe = yoe*365 + yoe/4 - yoe/100 + doy;
    let days = era*146097 + doe as i64 - 719468;
    let secs = days*86400 + (h*3600 + m*60 + sec) as i64;
    if secs < 0 { return None; }
    Some(std::time::UNIX_EPOCH + std::time::Duration::from_secs(secs as u64))
}

fn content_type_for(path: &str) -> &'static str {
    let ext = Path::new(path).extension().and_then(|e| e.to_str()).map(|s| s.to_ascii_lowercase()).unwrap_or_default();
    match ext.as_str() {
        "html"|"htm" => "text/html",
        "css" => "text/css",
        "js"|"mjs" => "application/javascript",
        "json" => "application/json",
        "png" => "image/png",
        "jpg"|"jpeg" => "image/jpeg",
        "gif" => "image/gif",
        "svg" => "image/svg+xml",
        "ico" => "image/x-icon",
        "txt" => "text/plain",
        "xml" => "text/xml",
        "woff" => "application/font-woff",
        "woff2" => "font/woff2",
        "ttf" => "font/ttf",
        "eot" => "application/vnd.ms-fontobject",
        "otf" => "font/otf",
        "mp4" => "video/mp4",
        "webm" => "video/webm",
        "pdf" => "application/pdf",
        "zip" => "application/zip",
        "wasm" => "application/wasm",
        "map" => "application/json",
        "md" => "text/markdown",
        "markdown" => "text/markdown",
        _ => "application/octet-stream",
    }
}

fn read_file_meta(p: &Path) -> Option<(Vec<u8>, std::time::SystemTime)> {
    let data = std::fs::read(p).ok()?;
    let meta = std::fs::metadata(p).ok()?;
    let mtime = meta.modified().ok()?;
    Some((data, mtime))
}

// Serve logic: handle one connection
fn handle_serve_conn(stream: std::net::TcpStream, dist_dir: &str, livereload: bool) {
    use std::io::{Read, Write};
    let mut s = stream;
    // Set timeout? Use blocking with small timeout
    let _ = s.set_read_timeout(Some(std::time::Duration::from_secs(5)));
    let mut buf = Vec::new();
    let mut tmp = [0u8; 8192];
    // Read until \r\n\r\n
    loop {
        match s.read(&mut tmp) {
            Ok(0) => return,
            Ok(n) => {
                buf.extend_from_slice(&tmp[..n]);
                if buf.windows(4).any(|w| w==b"\r\n\r\n") { break; }
                if buf.len() > 16384 { break; }
            },
            Err(_) => return,
        }
    }
    let req_str = String::from_utf8_lossy(&buf).to_string();
    let mut lines = req_str.lines();
    let request_line = lines.next().unwrap_or("");
    let parts: Vec<&str> = request_line.split_whitespace().collect();
    if parts.len() < 3 {
        return;
    }
    let method = parts[0];
    let raw_target = parts[1];
    // let version = parts[2];
    // Parse headers
    let mut headers: HashMap<String,String> = HashMap::new();
    for line in lines {
        if line.is_empty() { break; }
        if let Some(idx) = line.find(':') {
            let k = line[..idx].trim().to_ascii_lowercase();
            let v = line[idx+1..].trim().to_string();
            headers.insert(k, v);
        }
    }
    // Only GET, HEAD allowed
    if method != "GET" && method != "HEAD" {
        let date = http_date(std::time::SystemTime::now());
        let resp = format!("HTTP/1.1 405 Method Not Allowed\r\nallow: GET,HEAD\r\ncontent-length: 0\r\ndate: {}\r\nconnection: close\r\n\r\n", date);
        let _ = s.write_all(resp.as_bytes());
        return;
    }
    // Parse path: remove query, decode? For simplicity, take up to ?, decode %XX?
    let path_no_query = raw_target.split('?').next().unwrap_or("/");
    // Decode percent? Simple decode
    let mut decoded = String::new();
    let mut chars = path_no_query.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '%' {
            let h1 = chars.next().unwrap_or('0');
            let h2 = chars.next().unwrap_or('0');
            let hex = format!("{}{}", h1, h2);
            if let Ok(b) = u8::from_str_radix(&hex, 16) {
                decoded.push(b as char);
            } else {
                decoded.push('%'); decoded.push(h1); decoded.push(h2);
            }
        } else {
            decoded.push(c);
        }
    }
    let mut req_path = decoded;
    // Prevent traversal: if contains .. that would escape, return 404
    // Normalize: remove leading /
    if req_path.starts_with('/') {
        req_path = req_path[1..].to_string();
    }
    // Check for .. components
    let is_traversal = req_path.split('/').any(|seg| seg=="..");
    // Also handle // etc? Simplify.
    let date_now = http_date(std::time::SystemTime::now());
    if is_traversal {
        let resp = format!("HTTP/1.1 404 Not Found\r\ncontent-length: 0\r\ndate: {}\r\nconnection: close\r\n\r\n", date_now);
        let _ = s.write_all(resp.as_bytes());
        return;
    }
    // Resolve file path within dist_dir
    let dist_path = Path::new(dist_dir);
    // Handle directory vs file
    // If req_path is empty (i.e., "/" ), serve index.html
    // If req_path ends with /, serve dir/index.html
    // If req_path is dir without slash and dir exists with index.html, redirect 307 to with slash
    // Else serve file
    let mut file_path: Option<PathBuf> = None;
    let mut is_dir_redirect: Option<String> = None;
    if req_path.is_empty() {
        let p = dist_path.join("index.html");
        if p.is_file() {
            file_path = Some(p);
        } else {
            // No index, 404 (as observed for empty public with only favicon? Actually for "/" with no index, serve returns 404)
            let resp = format!("HTTP/1.1 404 Not Found\r\ncontent-length: 0\r\ndate: {}\r\nconnection: close\r\n\r\n", date_now);
            let _ = s.write_all(resp.as_bytes());
            return;
        }
    } else if req_path.ends_with('/') {
        let sub = req_path.trim_end_matches('/');
        let p = if sub.is_empty() { dist_path.join("index.html") } else { dist_path.join(format!("{}/index.html", sub)) };
        if p.is_file() {
            file_path = Some(p);
        } else {
            let resp = format!("HTTP/1.1 404 Not Found\r\ncontent-length: 0\r\ndate: {}\r\nconnection: close\r\n\r\n", date_now);
            let _ = s.write_all(resp.as_bytes());
            return;
        }
    } else {
        // No trailing slash: check if file exists
        let p_file = dist_path.join(&req_path);
        if p_file.is_file() {
            file_path = Some(p_file);
        } else if p_file.is_dir() {
            // Redirect to with slash
            // Location should be /<req_path>/ (preserve query? No, just path)
            let loc = format!("/relserror");
            // Actually loc is "/"+req_path+"/"
            let loc = format!("/{}/", req_path);
            let resp = format!("HTTP/1.1 307 Temporary Redirect\r\nlocation: {}\r\ncontent-length: 0\r\ndate: {}\r\nconnection: close\r\n\r\n", loc, date_now);
            let _ = s.write_all(resp.as_bytes());
            return;
        } else {
            let resp = format!("HTTP/1.1 404 Not Found\r\ncontent-length: 0\r\ndate: {}\r\nconnection: close\r\n\r\n", date_now);
