                        let resp_head = format!("HTTP/1.1 416 Range Not Satisfiable\r\ncontent-type: {}\r\naccept-ranges: bytes\r\nlast-modified: {}\r\ncontent-range: bytes */{}\r\ncontent-length: 0\r\ndate: {}\r\nconnection: close\r\n\r\n", ctype, last_mod, data.len(), date_now);
                        let _ = s.write_all(resp_head.as_bytes());
