                    let sliced = data[start..=end].to_vec();
                    // Append script
                    let mut combined = sliced;
                    combined.extend_from_slice(LIVERELOAD_SCRIPT.as_bytes());
                    // Headers: content-range based on original, content-length combined len, last-modified from file
