                let _ = s.write_all(resp_head.as_bytes());
                if method == "GET" {
                    let _ = s.write_all(sliced);
                }
                return;
            }
        }
    }
    // Normal 200
    let last_mod = http_date(mtime);
    let resp_head = format!("HTTP/1.1 200 OK\r\ncontent-type: {}\r\naccept-ranges: bytes\r\nlast-modified: {}\r\ncontent-length: {}\r\ndate: {}\r\nconnection: close\r\n\r\n", ctype, last_mod, data.len(), date_now);
    let _ = s.write_all(resp_head.as_bytes());
    if method == "GET" {
        let _ = s.write_all(&data);
    }
}

enum RangeResult {
    Single(usize, usize),
    Suffix(usize),
    Invalid,
}
fn parse_range(hdr: &str, len: usize) -> RangeResult {
    // hdr like "bytes=0-4", "bytes=-5", "bytes=0-", "bytes=0-1,3-4" (multipart -> Invalid)
    let hdr = hdr.trim();
    if !hdr.starts_with("bytes=") {
        return RangeResult::Invalid;
    }
    let spec = &hdr["bytes=".len()..];
    if spec.contains(',') {
        return RangeResult::Invalid;
    }
    if let Some(idx) = spec.find('-') {
        let start_str = &spec[..idx];
        let end_str = &spec[idx+1..];
        if start_str.is_empty() {
            // suffix: "-N"
            if let Ok(n) = end_str.parse::<usize>() {
                if n == 0 {
                    return RangeResult::Invalid;
                }
                if n >= len {
                    // If suffix longer than file, return whole? Actually for serve, bytes=-5 with len 15 returns last 5. If N >= len, return whole? Let's handle: if N >= len, start 0? But observed? For len 15, -5 returns 10-14. Good. For -100 with len 15, should return 0-14? Let's implement: if n >= len, return 0..len-1? Actually spec says if suffix length larger, return entire. We'll do that.
                    // But need to check original behavior for suffix larger? Not tested. Assume whole.
                    return RangeResult::Suffix(len);
                }
                return RangeResult::Suffix(n);
            } else {
                return RangeResult::Invalid;
            }
        } else if end_str.is_empty() {
            // "N-"
            if let Ok(s) = start_str.parse::<usize>() {
                if s >= len {
                    return RangeResult::Invalid;
                }
                return RangeResult::Single(s, len-1);
            } else {
                return RangeResult::Invalid;
            }
        } else {
            // "N-M"
            if let (Ok(s), Ok(e)) = (start_str.parse::<usize>(), end_str.parse::<usize>()) {
                if s > e || s >= len {
                    return RangeResult::Invalid;
                }
                let e = e.min(len-1);
                return RangeResult::Single(s, e);
            } else {
                return RangeResult::Invalid;
            }
        }
    }
    RangeResult::Invalid
}

