                    // Need to handle: suffix range bytes=-N means last N bytes of original?
                    // Then + script? Let's implement.
                    let start = data.len().saturating_sub(suffix_len);
                    let end = data.len()-1;
                    let sliced = data[start..].to_vec();
                    let mut combined = sliced;
                    combined.extend_from_slice(LIVERELOAD_SCRIPT.as_bytes());
                    let last_mod = http_date(mtime);
                    let resp_head = format!("HTTP/1.1 206 Partial Content\r\ncontent-type: {}\r\naccept-ranges: bytes\r\nlast-modified: {}\r\ncontent-range: bytes {}-{}/{}\r\ncontent-length: {}\r\ndate: {}\r\nconnection: close\r\n\r\n", ctype, last_mod, start, end, data.len(), combined.len(), date_now);
                    let _ = s.write_all(resp_head.as_bytes());
                    if method == "GET" {
