            },
            RangeResult::Single(start, end) => {
                let sliced = &data[start..=end];
                let last_mod = http_date(mtime);
                let resp_head = format!("HTTP/1.1 206 Partial Content\r\ncontent-type: {}\r\naccept-ranges: bytes\r\nlast-modified: {}\r\ncontent-range: bytes {}-{}/{}\r\ncontent-length: {}\r\ndate: {}\r\nconnection: close\r\n\r\n", ctype, last_mod, start, end, data.len(), sliced.len(), date_now);
                let _ = s.write_all(resp_head.as_bytes());
                if method == "GET" {
                    let _ = s.write_all(sliced);
                }
                return;
            },
            RangeResult::Suffix(n) => {
                let start = data.len().saturating_sub(n);
