                    return Some(ExitCode::from(0));
                },
                _ => return None,
            }
        }
    }
    // Check for version: -V / --version at top level (before subcommand or without subcommand)
    // Original: --version/-V only valid at top, not after subcommand (build --version gives error with tip).
    // So only handle if version flag appears before any subcommand (or no subcommand).
    // Find first subcommand index
    let first_sub_idx = args.iter().position(|a| a=="build"||a=="dev"||a=="serve"||a=="generate"||a=="help");
    let version_idx = args.iter().position(|a| a=="--version"||a=="-V");
    if let Some(vi) = version_idx {
        if first_sub_idx.is_none() || vi < first_sub_idx.unwrap() {
            // Top version
            println!("oranda 0.6.5");
            return Some(ExitCode::from(0));
        } else {
            // Version after subcommand: let clap handle error (will give tip for --version)
            return None;
        }
    }
    None
}

fn main() -> ExitCode {
    let all_args: Vec<String> = std::env::args().skip(1).collect();
    // Manual help/version handling first (takes precedence)
    if let Some(code) = handle_manual_help(&all_args) {
        return code;
    }
    // Now use clap for parsing (help/version disabled? No, keep enabled but our manual already handled help/version, so remaining won't contain help/version that should show help.
    // However clap will still handle -h/--help if we didn't catch? We caught all, so fine.
    // But to avoid double handling, we keep clap's help enabled; it won't trigger since we already returned for help cases.
    let m = match build_cli().try_get_matches() {
        Ok(m) => m,
        Err(e) => {
            // Clap error: need to print to correct stream and exit code.
            // e.exit_code() gives 0 for help/version (but we already handled help/version, so remaining errors are exit 2)
            // Use e.render() ?
            // In clap 4, e.exit() prints and exits. But we want to return ExitCode, not exit directly, to allow testing? Use e.render() and print.
            // e.render() returns styled output? Need to print to stderr for errors, stdout for help/version (but help/version already handled).
            // For errors, print to stderr.
            // Use `e.print()`? That prints to appropriate stream and returns ()? Actually `e.exit()` exits process. We want to mimic but return code.
            // Let's use: eprintln!("{}", e); and return code 2? But e's Display includes "error: ..." + usage. Good.
            // However e's message uses bin name dynamically (oranda vs executable)? Clap uses actual bin name, good.
            // For errors, clap's output goes to stderr, exit 2. Good.
            // So: 
            let code = e.exit_code();
            // Print to stderr if code !=0 else stdout? For help/version, code 0 to stdout, but we already handled those, so remaining are errors to stderr.
            // Use e.render().to_string()? Simpler: let _ = e.print(); then std::process::exit(code)
            // But e.print() exits? No, e.print() prints and returns Result, not exit. e.exit() exits.
            // We'll do:
            let _ = e.print();
            return ExitCode::from(code as u8);
        }
    };
    let verbose = m.get_one::<bool>("verbose").copied().unwrap_or(false);
    let output_format = m.get_one::<String>("output-format").map(|s| s.as_str()).unwrap_or("human");
    let json_mode = output_format == "json";

    match m.subcommand() {
        Some(("build", sub)) => {
            let json_only = sub.get_one::<bool>("json-only").copied().unwrap_or(false);
            return do_build(json_only, verbose, json_mode);
        },
        Some(("serve", sub)) => {
            let port = sub.get_one::<u16>("port").copied().unwrap_or(7979);
            return do_serve(port, verbose, json_mode);
        },
        Some(("dev", sub)) => {
            let port = sub.get_one::<u16>("port").copied();
            let no_first = sub.get_one::<bool>("no-first-build").copied().unwrap_or(false);
            let inc: Vec<String> = sub.get_many::<String>("include-paths").map(|v| v.cloned().collect()).unwrap_or_default();
            return do_dev(port, no_first, inc, verbose, json_mode);
        },
        Some(("generate", sub)) => {
            match sub.subcommand() {
                Some(("ci", _ci_sub)) => {
                    return do_generate(json_mode);
                },
                _ => {
                    // generate without subcommand: clap should have errored due to subcommand_required, but our manual help didn't catch? Actually generate without subcommand should error with help to stderr exit 2 (as observed).
                    // Since we set subcommand_required(true) for generate, try_get_matches would have errored and returned Err above, not Ok. So this branch shouldn't happen.
                    // But if it does (e.g., generate with -o but no ci), we should error similarly.
                    // For safety, just error.
                    // Let clap handle? It already would have errored. So unreachable.
                    return ExitCode::from(2);
                }
            }
        },
        _ => {
            // No subcommand (should have been handled by manual help for empty, or clap error for missing). If we reach here, it means no subcommand but not empty? Unlikely.
            return ExitCode::from(2);
        }
    }
}
